<?php declare(strict_types=1);namespace App\Models;final class Post extends Model{protected static string $table='posts';protected static array $json=['title','excerpt','blocks'];public static function published(int $d=20,int $B=1):array{$b=static::query()->where('is_published',1)->where('published_at','<=',now())->orderBy('published_at','DESC')->paginate($B,$d);$b['items']=static::castAll($b['items']);return $b;}public static function findBySlug(string $P):?array{return static::cast(static::query()->where('slug',$P)->where('is_published',1)->first());}}